// SQL cheat sheet. Ortak içerik tek yerde; lehçeye göre farklılaşan maddeler `d` alanıyla override edilir.
// buildSql(lehçe) ortak içeriği alıp override'ları uygular ve Topic[] üretir.
import type { Item, Topic } from './types'

export type Dialect = 'mysql' | 'mssql' | 'postgres' | 'sqlite'
type Over = Partial<Record<Dialect, Partial<Item>>>
type DItem = Item & { d?: Over }
type DTopic = Omit<Topic, 'items'> & { items: DItem[] }

export const dialectTitles: Record<Dialect, string> = {
  mysql: 'MySQL',
  mssql: 'SQL Server (T-SQL)',
  postgres: 'PostgreSQL',
  sqlite: 'SQLite',
}

const engineDesc: Record<Dialect, string> = {
  mysql: 'Web sitelerinde en yaygın açık kaynak veritabanı; WordPress ve PHP projelerinin standart tercihi.',
  mssql: 'Microsoft\'un veritabanı; C#/.NET projelerinin standart tercihi. SQL lehçesine T-SQL denir.',
  postgres: 'En gelişmiş açık kaynak veritabanı; standartlara en yakın SQL, JSON ve ileri özellikler.',
  sqlite: 'Sunucusuz, tek dosyada çalışan hafif veritabanı; mobil uygulamalar ve küçük projeler için.',
}

export function sqlGiris(dialect: Dialect): { q: string; a: string }[] {
  const t = dialectTitles[dialect]
  return [
    { q: 'SQL nedir?', a: 'Veritabanındaki tablolara soru sorma ve veri değiştirme dili. Programlama dili değil, sorgu dilidir.' },
    { q: `${t} nedir?`, a: engineDesc[dialect] },
    { q: 'Ne işe yarar?', a: 'Kayıt ekleme, arama, güncelleme, silme ve raporlama; verinin kalıcı ve düzenli tutulmasını sağlar.' },
    { q: 'Nerelerde kullanılır?', a: 'Her web ve mobil uygulamanın arkasında; e-ticaret, bankacılık, raporlama, kullanıcı yönetimi.' },
    { q: 'Tablo, satır, sütun nedir?', a: 'Tablo bir Excel sayfası gibidir: sütunlar alanlar (ad, yaş), satırlar kayıtlar (her kişi bir satır).' },
    { q: 'Lehçe (dialect) nedir?', a: 'Temel SQL her veritabanında aynıdır; sınırlama, otomatik id, tarih fonksiyonları gibi ayrıntılar farklıdır. Bu bölüm ' + t + ' yazımını gösterir.' },
    { q: 'SQL kodu nasıl çalışır?', a: 'Sorguyu veritabanı sunucusuna gönderirsin, sunucu tabloları okuyup sonucu satırlar halinde döner. Uygulama kodu (C#, Python, PHP) bu sorguları çağırır.' },
    { q: 'Programlama dilleriyle ilişkisi?', a: 'C#, Python, Java gibi diller SQL cümlesini metin olarak gönderir; parametreli sorgu ile değerler güvenle eklenir.' },
    { q: 'Öğrenirken hangi araçlar kullanılır?', a: dialect === 'sqlite' ? 'DB Browser for SQLite veya VS Code SQLite eklentisi; kurulum gerektirmez, tek dosya yeter.' : dialect === 'mssql' ? 'SQL Server Express ve SSMS (SQL Server Management Studio); ikisi de ücretsiz.' : dialect === 'postgres' ? 'PostgreSQL kurulumu ve pgAdmin veya DBeaver; hepsi ücretsiz.' : 'MySQL Community Server ve MySQL Workbench veya DBeaver; XAMPP ile de gelir.' },
  ]
}

