// Ortak içeriği alıp lehçe override'larını uygular.
export function buildSql(dialect: Dialect): Topic[] {
  return base.map((t) => ({
    id: t.id,
    title: t.title,
    intro: t.intro,
    items: t.items.map(({ d, ...item }) => ({ ...item, ...(d?.[dialect] ?? {}) })),
  }))
}
